const input = $input.first().json;
const body = input.body || input;

const errors = [];

if (!body.query) {
  errors.push('Missing required parameter: query');
}

if (!body.google_api_key) {
  errors.push('Missing required parameter: google_api_key');
}

if (!body.anthropic_api_key && !body.openai_api_key) {
  errors.push('Missing API key: anthropic_api_key or openai_api_key required for recipe extraction');
}

if (errors.length > 0) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: errors.join(', '),
        status: 'BAD_REQUEST'
      }
    }
  }];
}

const prefs = body.preferences || {};

return [{
  json: {
    valid: true,
    query: body.query,
    google_api_key: body.google_api_key,
    anthropic_api_key: body.anthropic_api_key,
    openai_api_key: body.openai_api_key,
    user_id: body.user_id,
    language: prefs.language || 'fr',
    max_videos: prefs.max_videos || 1,
    prefer_short: prefs.prefer_short || false,
    n8n_webhook_url: process.env.N8N_WEBHOOK_URL || 'http://localhost:5678'
  }
}];

const input = $input.first().json;
const prevData = $('Validate Input').first().json;

const video = input.items[0];
const videoId = video.id?.videoId;

return [{
  json: {
    ...prevData,
    video: {
      id: videoId,
      title: video.snippet?.title,
      description: video.snippet?.description,
      channel: video.snippet?.channelTitle,
      thumbnail: video.snippet?.thumbnails?.high?.url || video.snippet?.thumbnails?.default?.url,
      url: `https://www.youtube.com/watch?v=${videoId}`,
      published_at: video.snippet?.publishedAt
    },
    video_url: `https://www.youtube.com/watch?v=${videoId}`
  }
}];

